INSERT INTO discipline_question_bank (discipline,id,payload) VALUES
('jogos-digitais','q01','{"text":"Em jogos como GTA IV, Niko Bellic é controlado pelo jogador. Que elemento ele representa?","options":["Cenário","Personagem","Engine","Banco de dados"],"correct":1}'),
('jogos-digitais','q02','{"text":"Em The Legend of Zelda, uma espada que pode ser coletada e usada pelo herói é um exemplo de:","options":["Objeto do jogo","Folha de estilo","Servidor","Repositório"],"correct":0}'),
('jogos-digitais','q03','{"text":"No universo de Super Mario, castelos, plataformas e caminhos formam principalmente o:","options":["Código HTML","Cenário","Backend","Preço do jogo"],"correct":1}'),
('jogos-digitais','q04','{"text":"O que é uma engine de jogos?","options":["Uma loja de jogos","Um personagem inimigo","Uma ferramenta que reúne recursos para criar jogos","Um tipo de imagem"],"correct":2}'),
('jogos-digitais','q05','{"text":"Qual alternativa apresenta exemplos de engines usadas no desenvolvimento de jogos?","options":["HTML e CSS","GitHub e VS Code","Unity, Unreal Engine e Godot","Chrome e Firefox"],"correct":2}'),
('jogos-digitais','q06','{"text":"Para que serve o GitHub em um projeto de jogo?","options":["Editar imagens automaticamente","Hospedar e controlar versões do código","Criar personagens em 3D sozinho","Definir o preço do jogo"],"correct":1}'),
('jogos-digitais','q07','{"text":"O VS Code é usado principalmente para:","options":["Escrever e editar código","Vender jogos","Desenhar mapas em papel","Hospedar partidas online"],"correct":0}'),
('jogos-digitais','q08','{"text":"O HTML é responsável principalmente por:","options":["Estruturar o conteúdo de uma página web","Calcular o preço do jogo","Criar sons","Guardar arquivos no GitHub"],"correct":0}'),
('jogos-digitais','q09','{"text":"O CSS é usado principalmente para:","options":["Criar o banco de dados","Estilizar cores, tamanhos e posições na página","Controlar versões do código","Compilar uma engine"],"correct":1}'),
('jogos-digitais','q10','{"text":"Em um jogo 2D, o que é um sprite?","options":["Uma imagem que representa um elemento do jogo","Um tipo de servidor","Uma profissão","Um comando do GitHub"],"correct":0}'),
('jogos-digitais','q11','{"text":"Vários quadros de animação reunidos em uma única imagem formam uma:","options":["Spritesheet","Planilha","Página HTML","Tabela de preços"],"correct":0}'),
('jogos-digitais','q12','{"text":"Qual profissional trabalha na parte visual e interativa que o usuário vê?","options":["Backend","Frontend","Contabilidade","Suporte de rede"],"correct":1}'),
('jogos-digitais','q13','{"text":"Qual área normalmente cuida das regras no servidor e do acesso ao banco de dados?","options":["Frontend","Pixel art","Backend","Level design"],"correct":2}'),
('jogos-digitais','q14','{"text":"O profissional que atua tanto no frontend quanto no backend é chamado de:","options":["Full stack","Trainee","Designer gráfico","Jogador profissional"],"correct":0}'),
('jogos-digitais','q15','{"text":"O que caracteriza um profissional trainee?","options":["Está em período inicial de formação e desenvolvimento na empresa","É sempre o líder técnico","Possui obrigatoriamente mais de dez anos de experiência","Trabalha apenas com CSS"],"correct":0}'),
('jogos-digitais','q16','{"text":"Um desenvolvedor júnior geralmente:","options":["Está no início da carreira e recebe orientação","Define sozinho toda a estratégia da empresa","Não precisa estudar","Só pode trabalhar com jogos 3D"],"correct":0}'),
('jogos-digitais','q17','{"text":"Um desenvolvedor pleno geralmente possui:","options":["Mais autonomia e experiência para resolver tarefas","Menos conhecimento que um trainee","Apenas conhecimentos de HTML","Nenhuma responsabilidade no projeto"],"correct":0}'),
('jogos-digitais','q18','{"text":"Um desenvolvedor sênior geralmente:","options":["Resolve problemas complexos e pode orientar a equipe","Está começando o primeiro estágio","Trabalha somente com sprites","Não toma decisões técnicas"],"correct":0}'),
('jogos-digitais','q19','{"text":"O que significa precificação de um jogo?","options":["Escolher os personagens","Definir quanto o produto será vendido","Criar o código-fonte","Desenhar o cenário"],"correct":1}'),
('jogos-digitais','q20','{"text":"Qual item deve ser considerado na precificação de um jogo?","options":["Custos de produção, público e mercado","Somente a cor do personagem","Apenas o nome da engine","Somente a quantidade de arquivos HTML"],"correct":0}'),
('jogos-digitais','q21','{"text":"Em GTA IV, a cidade explorada pelo jogador funciona como:","options":["Cenário de mundo aberto","Sprite do personagem","Código CSS","Repositório Git"],"correct":0}'),
('jogos-digitais','q22','{"text":"Em Zelda, poções, chaves e escudos são exemplos de:","options":["Objetos ou itens do jogo","Engines","Linguagens de marcação","Cargos profissionais"],"correct":0}'),
('jogos-digitais','q23','{"text":"Em Super Mario, Mario, Luigi e Bowser são exemplos de:","options":["Personagens","Servidores","Folhas CSS","Bancos de dados"],"correct":0}'),
('jogos-digitais','q24','{"text":"Quando Mario encosta em uma moeda e o jogo detecta esse contato, ocorre uma:","options":["Colisão","Precificação","Publicação no GitHub","Formatação HTML"],"correct":0}'),
('jogos-digitais','q25','{"text":"Um personagem controlado pelo computador, e não pelo jogador, é chamado de:","options":["NPC","CSS","Engine","Commit"],"correct":0}'),
('jogos-digitais','q26','{"text":"O personagem controlado diretamente pela pessoa que está jogando é o:","options":["Personagem jogável","Servidor","Cenário","Repositório"],"correct":0}'),
('jogos-digitais','q27','{"text":"Vida, pontuação e moedas exibidas na tela fazem parte da:","options":["Interface do jogador (HUD)","Engine física","Precificação","Hospedagem Git"],"correct":0}'),
('jogos-digitais','q28','{"text":"Uma tela como menu, fase ou game over pode ser organizada na engine como uma:","options":["Cena","Profissão","Folha de pagamento","Branch"],"correct":0}'),
('jogos-digitais','q29','{"text":"Se o mesmo objeto “Moeda” aparece dez vezes na fase, cada aparição é uma:","options":["Instância do objeto","Nova engine","Página HTML","Equipe full stack"],"correct":0}'),
('jogos-digitais','q30','{"text":"Imagens, músicas, sons e fontes usados no jogo são chamados de:","options":["Assets ou recursos","Salários","Branches","Servidores backend"],"correct":0}'),
('jogos-digitais','q31','{"text":"O ciclo que atualiza ações, movimentos e imagens várias vezes por segundo é o:","options":["Game loop","README","Preço final","Plano de carreira"],"correct":0}'),
('jogos-digitais','q32','{"text":"A regra “se pegar a moeda, somar um ponto” é um exemplo de:","options":["Evento do jogo","Contrato de trabalho","Estilo CSS","Repositório remoto"],"correct":0}'),
('jogos-digitais','q33','{"text":"No GitHub, um commit serve para:","options":["Registrar um conjunto de alterações no projeto","Criar um sprite automaticamente","Calcular a nota da prova","Comprar uma engine"],"correct":0}'),
('jogos-digitais','q34','{"text":"No GitHub, um repositório é:","options":["O local onde os arquivos e o histórico do projeto ficam organizados","Um personagem secreto","Uma animação de corrida","Um efeito de CSS"],"correct":0}'),
('jogos-digitais','q35','{"text":"Em uma página de jogo na web, qual tecnologia pode criar títulos, botões e áreas de conteúdo?","options":["HTML","Precificação","Sprite","Cargo sênior"],"correct":0}'),
('jogos-digitais','q36','{"text":"Para mudar a cor e o tamanho de um botão de um jogo web, usamos principalmente:","options":["CSS","GitHub Issues","Backend","Engine física"],"correct":0}'),
('jogos-digitais','q37','{"text":"Salvar a pontuação de vários jogadores em um banco de dados é uma tarefa ligada principalmente ao:","options":["Backend","Sprite","Cenário","CSS"],"correct":0}'),
('jogos-digitais','q38','{"text":"Exibir na tela o botão “Jogar novamente” é uma tarefa ligada principalmente ao:","options":["Frontend","Banco de dados","Controle de versão","Preço de venda"],"correct":0}'),
('jogos-digitais','q39','{"text":"Gravidade, colisões e animações prontas são recursos que uma engine pode oferecer para:","options":["Facilitar o desenvolvimento do jogo","Substituir toda a equipe","Definir o salário do programador","Vender o jogo automaticamente"],"correct":0}'),
('jogos-digitais','q40','{"text":"Na equipe de uma missão final, quem tem mais experiência e costuma orientar decisões técnicas?","options":["Trainee","Júnior","Sênior","Jogador"],"correct":2}');
